class Solution {
public:
    int numPairsDivisibleBy60(vector<int>& time) {
        vector<int> cnt(60, 0);
        int pairs = 0;
        for (int i = 0; i < (int)time.size(); i++) {
            int r = time[i] % 60;
            pairs += cnt[(60 - r) % 60];
            cnt[r]++;
        }
        return pairs;
    }
};
